#define MAXN 11

char s[MAXN];
int N;
int oldDigits[MAXN];
int used[10];
int bestDigits[MAXN];
int curDigits[MAXN];
int found = 0;

/*
We maximize:
    diff(a,b) = min(|a-b|, 10^N - |a-b|)

For fixed old password A, the best possible value is achieved by making
the circular distance as close as possible to 10^N / 2.

So candidates are numbers near:
    A + 10^(N-1)*5... actually modulo 10^N:
    target = A + 10^N/2  (mod 10^N)

If 10^N is even (always true for N>=1), the maximum possible circular
distance is exactly 10^N/2, and it is achieved uniquely modulo 10^N by
target = A + 10^N/2 (mod 10^N).

Thus we only need:
1) If target itself has all distinct digits, answer it.
2) Otherwise, among all distinct-digit N-digit strings (allowing leading
   zeros because password length is fixed), minimize circular distance to
   target. If tie, choose smaller numeric value.

Circular distance to target T for candidate X:
    min((X-T mod M), (T-X mod M))
equivalently shortest distance on circle.

We construct the smallest valid number for each possible distance d from 0
upward:
    X = T - d (mod M)
    X = T + d (mod M)
and choose the first valid one; for same d check smaller numeric value first.

Since N <= 10 (because digits must appear at most once), brute checking each
distance up to M/2 is too much for large N. Instead, we do digit-DP style
search for the smallest distinct-digit number in intervals.

For a given interval [L, R], find the smallest N-digit string with distinct
digits whose numeric value lies in [L, R]. Then for each d we need points,
but better: binary-search-like expansion isn't enough.

Instead, because target distance search corresponds to two intervals:
numbers within distance <= d from T on the circle.
We can binary search minimal d for which such a number exists, using interval
existence DP, then recover smallest number among those intervals.

Need routines:
- exists/smallest distinct-digit number in [L,R] over fixed length N with
  leading zeros allowed.

This is standard digit DP/backtracking with bounds and used digits.
*/

long long pow10[MAXN];
long long MOD;
long long target;

int ansDigits[MAXN];

bool buildSmallestInRangeRec(int pos, int tightL, int tightR, long long L, long long R) {
    if (pos == N) return true;

    int low = tightL ? (int)((L / pow10[N - 1 - pos]) % 10) : 0;
    int high = tightR ? (int)((R / pow10[N - 1 - pos]) % 10) : 9;

    for (int d = low; d <= high; d++) {
        if (used[d]) continue;
        used[d] = 1;
        ansDigits[pos] = d;

        int nTightL = tightL && (d == low);
        int nTightR = tightR && (d == high);

        if (buildSmallestInRangeRec(pos + 1, nTightL, nTightR, L, R)) return true;

        used[d] = 0;
    }
    return false;
}

bool smallestInRange(long long L, long long R, int out[]) {
    if (L > R) return false;
    memset(used, 0, sizeof(used));
    if (!buildSmallestInRangeRec(0, 1, 1, L, R)) return false;
    for (int i = 0; i < N; i++) out[i] = ansDigits[i];
    return true;
}

bool existsInRange(long long L, long long R) {
    int tmp[MAXN];
    return smallestInRange(L, R, tmp);
}

long long digitsToValue(int d[]) {
    long long v = 0;
    for (int i = 0; i < N; i++) v = v * 10 + d[i];
    return v;
}

void copyDigits(int dst[], int src[]) {
    for (int i = 0; i < N; i++) dst[i] = src[i];
}

int main() {
    if (scanf("%10s", s) != 1) return 0;
    N = (int)strlen(s);

    if (N > 10) return 0; // impossible under distinct-digit constraint

    pow10[0] = 1;
    for (int i = 1; i <= N; i++) pow10[i] = pow10[i - 1] * 10LL;
    MOD = pow10[N];

    long long oldVal = 0;
    for (int i = 0; i < N; i++) {
        oldDigits[i] = s[i] - '0';
        oldVal = oldVal * 10 + oldDigits[i];
    }

    target = (oldVal + MOD / 2) % MOD;

    // Binary search minimal circular distance from target to any valid password
    long long lo = 0, hi = MOD / 2;
    while (lo < hi) {
        long long mid = (lo + hi) / 2;
        bool ok = false;

        long long L1 = target - mid, R1 = target + mid;
        if (L1 >= 0 && R1 < MOD) {
            ok = existsInRange(L1, R1);
        } else {
            // wrapped interval
            long long a1 = 0, b1 = R1 % MOD;
            long long a2 = (L1 % MOD + MOD) % MOD, b2 = MOD - 1;
            ok = existsInRange(a1, b1) || existsInRange(a2, b2);
        }

        if (ok) hi = mid;
        else lo = mid + 1;
    }

    long long d = lo;
    int cand1[MAXN], cand2[MAXN];
    bool ok1 = false, ok2 = false;

    long long L1 = target - d, R1 = target + d;
    if (L1 >= 0 && R1 < MOD) {
        ok1 = smallestInRange(L1, R1, cand1);
    } else {
        // wrapped: union [0, R1%MOD] and [(L1 mod MOD), MOD-1]
        int t1[MAXN], t2[MAXN];
        bool e1 = smallestInRange(0, R1 % MOD, t1);
        bool e2 = smallestInRange((L1 % MOD + MOD) % MOD, MOD - 1, t2);
        if (e1 && e2) {
            if (digitsToValue(t1) <= digitsToValue(t2)) copyDigits(cand1, t1);
            else copyDigits(cand1, t2);
            ok1 = true;
        } else if (e1) {
            copyDigits(cand1, t1);
            ok1 = true;
        } else if (e2) {
            copyDigits(cand1, t2);
            ok1 = true;
        }
    }

    // Among numbers at exact minimal circular distance d from target,
    // the set found by interval [target-d, target+d] may include closer values.
    // Since d is minimal possible, any valid value in that interval must actually
    // have distance exactly d.
    // So cand1 is sufficient.

    for (int i = 0; i < N; i++) putchar(cand1[i] + '0');
    putchar('\n');

    return 0;
}

