int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s;
    if (!(cin >> s)) return 0;

    int n = (int)s.size();

    // N=1: every 1-digit password already has unique digits requirement.
    // Maximize circular distance on modulo 10.
    if (n == 1) {
        int x = s[0] - '0';
        int best = -1, ans = 0;
        for (int y = 0; y <= 9; ++y) {
            int d = abs(x - y);
            d = min(d, 10 - d);
            if (d > best || (d == best && y < ans)) {
                best = d;
                ans = y;
            }
        }
        cout << ans << '\n';
        return 0;
    }

    // For n >= 2, since digits in the new password must be all distinct,
    // n cannot exceed 10 in meaningful test data.
    long long oldVal = stoll(s);

    vector<int> digits(10);
    iota(digits.begin(), digits.end(), 0);

    long long mod = 1;
    for (int i = 0; i < n; ++i) mod *= 10LL;

    long long bestDist = -1;
    long long bestVal = -1;

    // Generate all n-digit numbers with distinct digits.
    // Leading zero is not allowed because the new password must have the same number of digits.
    function<void(int, long long, int)> dfs = [&](int pos, long long cur, int usedMask) {
        if (pos == n) {
            long long diff = llabs(cur - oldVal);
            long long dist = min(diff, mod - diff);
            if (dist > bestDist || (dist == bestDist && cur < bestVal)) {
                bestDist = dist;
                bestVal = cur;
            }
            return;
        }

        for (int d = 0; d <= 9; ++d) {
            if (usedMask & (1 << d)) continue;
            if (pos == 0 && d == 0) continue; // keep exactly n digits
            dfs(pos + 1, cur * 10 + d, usedMask | (1 << d));
        }
    };

    dfs(0, 0, 0);

    cout << bestVal << '\n';
    return 0;
}

