public class PasswordGenerator {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String oldPassword = sc.next().trim();
        sc.close();

        int n = oldPassword.length();
        long oldNum = Long.parseLong(oldPassword);
        long mod = (long) Math.pow(10, n);
        long half = mod / 2;

        // Try offsets around half
        long bestDiff = -1;
        long bestCandidate = Long.MAX_VALUE;

        // Search around half distance
        for (long offset = 0; offset <= half; offset++) {
            for (long sign = -1; sign <= 1; sign += 2) {
                long candidate = (oldNum + sign * (half - offset) + mod) % mod;
                if (hasDistinctDigits(candidate, n)) {
                    long diff = Math.min(Math.abs(candidate - oldNum), mod - Math.abs(candidate - oldNum));
                    if (diff > bestDiff || (diff == bestDiff && candidate < bestCandidate)) {
                        bestDiff = diff;
                        bestCandidate = candidate;
                    }
                }
                if (offset == 0) break; // avoid duplicate for offset=0
            }
            // Early stop if we found a maximum possible distance
            if (bestDiff == half) break;
        }

        // Format output with leading zeros if needed
        System.out.printf("%0" + n + "d%n", bestCandidate);
    }

    private static boolean hasDistinctDigits(long num, int n) {
        boolean[] seen = new boolean[10];
        String s = String.format("%0" + n + "d", num);
        for (char c : s.toCharArray()) {
            int d = c - '0';
            if (seen[d]) return false;
            seen[d] = true;
        }
        return true;
    }
}

