            if (circDiff > bestDiff || (circDiff == bestDiff && val < bestCandidate)) {
                bestDiff = circDiff;
                bestCandidate = val;
            }
            return;
        }
        for (int d = 0; d <= 9; d++) {
            if (!used[d]) {
                used[d] = true;
                digits[pos] = d;
                generate(digits, used, pos + 1);
                used[d] = false;
            }
        }
