public class Main {
    static int N;
    static char[] oldPwd;
    static boolean[] used = new boolean[10];
    static char[] current;
    static char[] best;
    static long MOD;
    static long oldValue;
    static long bestDiff = -1;
    static long bestValue = -1;

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();

        oldPwd = s.toCharArray();
        N = s.length();
        current = new char[N];
        MOD = 1;
        for (int i = 0; i < N; i++) MOD *= 10L;
        oldValue = Long.parseLong(s);

        dfs(0);

        System.out.println(new String(best));
    }

    static void dfs(int pos) {
        if (pos == N) {
            if (current[0] == '0' && N > 1) return; // must have exactly N digits

            long val = 0;
            for (int i = 0; i < N; i++) {
                val = val * 10 + (current[i] - '0');
            }

            long d = Math.abs(val - oldValue);
            long diff = Math.min(d, MOD - d);

            if (diff > bestDiff || (diff == bestDiff && val < bestValue)) {
                bestDiff = diff;
                bestValue = val;
                best = current.clone();
            }
            return;
        }

        for (int d = 0; d <= 9; d++) {
            if (!used[d]) {
                if (pos == 0 && d == 0 && N > 1) continue; // leading zero not allowed
                used[d] = true;
                current[pos] = (char) ('0' + d);
                dfs(pos + 1);
                used[d] = false;
            }
        }
    }
}

import sys
from functools import lru_cache

def main():
    s = sys.stdin.readline().strip()
    n = len(s)
    old_digits = list(map(int, s))
    total = 10 ** n
    full_mask = (1 << 10) - 1

    # Build maximum number <= bound using distinct digits from available mask.
    def best_le(mask, bound_digits):
        @lru_cache(None)
        def dp(pos, tight, started_mask):
            # started_mask is just mask of used digits so far; available are in outer mask
            if pos == n:
                return ()
            limit = bound_digits[pos] if tight else 9
            best = None
            used = started_mask
            for d in range(limit, -1, -1):
                if not (mask >> d) & 1:
                    continue
                if (used >> d) & 1:
                    continue
                if pos == 0 and n > 1 and d == 0:
                    continue
                ntight = tight and (d == limit)
                tail = dp(pos + 1, ntight, used | (1 << d))
                if tail is not None:
                    cand = (d,) + tail
                    best = cand
                    break
            return best

        res = dp(0, True, 0)
        dp.cache_clear()
        if res is None:
            return None
        return int(''.join(map(str, res)))

    # Build minimum number >= bound using distinct digits from available mask.
    def best_ge(mask, bound_digits):
        @lru_cache(None)
        def dp(pos, tight, used):
            if pos == n:
                return ()
            limit = bound_digits[pos] if tight else 0
            for d in range(limit, 10):
                if not (mask >> d) & 1:
                    continue
                if (used >> d) & 1:
                    continue
                if pos == 0 and n > 1 and d == 0:
                    continue
                ntight = tight and (d == limit)
                tail = dp(pos + 1, ntight, used | (1 << d))
                if tail is not None:
                    return (d,) + tail
            return None

        res = dp(0, True, 0)
        dp.cache_clear()
        if res is None:
            return None
        return int(''.join(map(str, res)))

    # Need candidates near old + total//2 and old - total//2 on the circle.
    old_val = int(s)
    half = total // 2

    candidates = set()

    # Around old + half
    t1 = (old_val + half) % total
    bd1 = list(map(int, str(t1).zfill(n)))
    x = best_ge(full_mask, bd1)
    if x is not None:
        candidates.add(x)
    y = best_le(full_mask, bd1)
    if y is not None:
        candidates.add(y)

    # Around old - half
    t2 = (old_val - half) % total
    bd2 = list(map(int, str(t2).zfill(n)))
    x = best_ge(full_mask, bd2)
    if x is not None:
        candidates.add(x)
    y = best_le(full_mask, bd2)
    if y is not None:
        candidates.add(y)

    # Evaluate all candidates by circular distance, tie by smaller integer value.
    def circ_dist(a, b):
        d = abs(a - b)
        return min(d, total - d)

    best_ans = None
    best_dist = -1
    for cand in candidates:
        if len(str(cand)) != n and not (cand == 0 and n == 1):
            # exclude leading-zero shorter numbers
            continue
        d = circ_dist(cand, old_val)
        if d > best_dist or (d == best_dist and (best_ans is None or cand < best_ans)):
            best_dist = d
            best_ans = cand

    print(str(best_ans).zfill(n))

